/// <reference types="@moyarich/moyaforge-mdx/virtual" preserve="true" />

import type { ReactNode } from "react";
import type { RegistryPage } from "@moyarich/moyaforge-mdx";
import { RegistryRouteView } from "./routing/ErrorBoundary.js";
import { routes } from "virtual:moyaforge-mdx/metadata";
import { sources } from "virtual:moyaforge-mdx/lazy-registry";

/** Rendering overrides for routes generated by the MDX registry plugin. */
export interface RegistryRoutesProps {
  /** Content rendered when no registry route matches. */
  notFound?: ReactNode;
  /** Fallback displayed while a lazy page loads. */
  fallback?: ReactNode;
  /** Wrap or customize a page using its registry metadata and rendered content. */
  renderPage?: (page: RegistryPage, content: ReactNode) => ReactNode;
}

/**
 * Render routes from the Vite-generated lazy MDX registry.
 * Mount once inside the consumer's existing React Router route tree.
 * Requires the MDX registry plugin to provide the virtual modules.
 * @param props - Optional loading, missing-route and page-rendering overrides.
 */

export function RegistryRoutes(props: RegistryRoutesProps) {
  return <RegistryRouteView routes={routes} sources={sources} {...props} />;
}
